const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
export const money=n=>n==null?'Chưa có dữ liệu':new Intl.NumberFormat('vi-VN',{maximumFractionDigits:8}).format(n)+' ₫';
export const time=s=>new Date(s).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',dateStyle:'short',timeStyle:'short'});
export function url(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
export function median(values){const a=values.filter(Number.isFinite).sort((a,b)=>a-b);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2:null}
export function comparable(report){return (report?.entries||[]).filter(e=>!e.exclude&&e.period===report.period&&e.account===report.account&&typeof e.price==='number'&&Number.isFinite(e.price)&&e.price>0)}
export function stats(report){const rows=comparable(report),reseller=rows.filter(e=>e.type==='reseller'),p=reseller.map(e=>e.price);return {rows,reseller,official:rows.filter(e=>e.type==='official'),min:p.length?Math.min(...p):null,median:median(p),max:p.length?Math.max(...p):null}}
function rowKey(e){return [e.seller.toLowerCase().trim(),e.plan.toLowerCase().trim(),e.period,e.account,e.url].join('|')}
export function trend(report,reports){const previous=reports.filter(r=>r.id!==report.id&&r.product.toLowerCase()===report.product.toLowerCase()&&r.period===report.period&&r.account===report.account&&new Date(r.createdAt)<new Date(report.createdAt)).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];if(!previous)return null;const map=new Map(stats(previous).reseller.map(e=>[rowKey(e),e.price]));const pairs=stats(report).reseller.filter(e=>map.has(rowKey(e))).map(e=>({seller:e.seller,before:map.get(rowKey(e)),after:e.price}));if(!pairs.length)return null;const before=median(pairs.map(p=>p.before)),after=median(pairs.map(p=>p.after));return {previous:previous.createdAt,count:pairs.length,before,after,change:(after-before)/before*100,pairs}}
export function confidence(report){const s=stats(report),domains=new Set(s.rows.map(e=>{try{return new URL(e.url).hostname}catch{return ''}})),fresh=s.rows.filter(e=>e.date&&!e.old&&!e.future);return s.reseller.length>=3&&s.official.length&&domains.size>=3&&fresh.length>=3?{label:'Trung bình',note:'Có nhiều nguồn và ngày đăng; cần kiểm tra lại trước khi chốt giá.'}:{label:'Thấp',note:'Thiếu nguồn tương đương, ngày đăng hoặc xác minh độc lập.'}}
export function normalizeReport(r){if(!r||typeof r.product!=='string'||!r.product.trim()||!Array.isArray(r.entries))throw new Error('Tệp không đúng định dạng báo cáo GiáSát.');return {...r,id:typeof r.id==='string'?r.id:uid(),product:r.product.slice(0,120),createdAt:r.createdAt||r.savedAt||new Date().toISOString(),period:['month','year'].includes(r.period)?r.period:'year',account:['Chính chủ','Cấp riêng','Dùng chung','Chưa rõ'].includes(r.account)?r.account:'Chính chủ',entries:r.entries.filter(e=>e&&url(e.url)&&typeof e.seller==='string').map(e=>({...e,id:e.id||uid(),plan:String(e.plan||''),price:typeof e.price==='number'&&Number.isFinite(e.price)&&e.price>0?e.price:null,origin:e.origin||'manual'})),news:Array.isArray(r.news)?r.news.filter(e=>url(e.url)):[],marketing:Array.isArray(r.marketing)?r.marketing.filter(e=>url(e.url)):[],sources:Array.isArray(r.sources)?r.sources.filter(e=>url(e.url)):[],warnings:Array.isArray(r.warnings)?r.warnings:[]}}
export function markdown(report,reports=[]){const s=stats(report),tr=trend(report,reports),c=confidence(report),tidy=v=>String(v||'Chưa có dữ liệu').replace(/[|\r\n]/g,' '),brief=(v,n)=>tidy(v).split(/\s+/).slice(0,n).join(' ');let sections=[`# ${report.product}\n${report.period==='year'?'1 năm':'1 tháng'} · ${report.account} · ${time(report.createdAt)}`,`## 📊 1. Tổng quan thị trường\n- Giá chính hãng: ${[...new Set(s.official.map(e=>money(e.price)))].slice(0,3).join(' / ')||'Chưa có dữ liệu'}.\n- Reseller: thấp nhất ${money(s.min)} / trung vị ${money(s.median)} / cao nhất ${money(s.max)}.\n- Xu hướng: ${tr?(tr.change>0?'Tăng':tr.change<0?'Giảm':'Ổn định')+' so với '+time(tr.previous)+' trên '+tr.count+' nguồn tương đương.':'Chưa có dữ liệu lịch sử tương đương.'}${report.fx?'\n- Tỷ giá: '+report.fx.rate+' VNĐ/USD ('+report.fx.date+'), [nguồn]('+report.fx.url+').':''}`,`## 📣 3. Cách đối thủ quảng cáo\n${report.marketing.slice(0,4).map(m=>'- '+brief(m.text,12)+' [Nguồn]('+m.url+')').join('\n')||'Chưa có dữ liệu.'}`,`## 🆕 4. Điểm mới đáng chú ý\n${report.news.slice(0,2).map(n=>'- '+brief(n.title,12)+' ('+(n.date||'không rõ ngày')+'). [Nguồn]('+n.url+')').join('\n')||'Chưa có dữ liệu.'}`,`## 💡 5. Gợi ý chiến lược định giá\n${s.reseller.length>=3?'Mức tham khảo: '+money(s.median)+'. Giá trung bình + bảo hành tốt; cần kiểm tra giá vốn, quyền phân phối và chi phí.':'Chưa đủ ba giá reseller cùng loại để đề xuất.'}\nRủi ro: biến động giá, điều khoản nhà phát hành.`, `## ✅ 6. Độ tin cậy\n${c.label}: ${c.note} Giá chưa được xác minh độc lập.`];const header='## 🏷️ 2. Bảng so sánh đối thủ\n| Đối thủ | Giá | Gói & thời hạn | Hình thức | Bảo hành | Khuyến mãi | Nguồn |\n| :--- | :--- | :--- | :--- | :--- | :--- | :--- |';let table=header,included=0;for(const e of report.entries.slice().sort((a,b)=>Number(a.exclude)-Number(b.exclude))){const line='\n| '+[brief(e.seller,5)+' ('+(e.type==='official'?'hãng':'reseller')+')',e.price!=null?money(e.price)+(e.currency==='USD'?' ('+e.amount+' USD)':''):'Chưa có dữ liệu',brief(e.plan,4)+' / '+(e.period==='year'?'năm':e.period==='month'?'tháng':'chưa rõ'),e.account,brief(e.warranty,5),brief(e.promo,5),'[Nguồn]('+e.url+') '+(e.date||'không rõ ngày')+(e.exclude?' · đã loại':'')].map(tidy).join(' | ')+' |';if([...sections,table+line].join('\n\n').split(/\s+/).length>475)break;table+=line;included++}if(included<report.entries.length)table+='\n\nBảng được rút gọn; bản JSON giữ toàn bộ nguồn.';return [sections[0],sections[1],table,...sections.slice(2)].join('\n\n')+'\n'}

